fn lo2(a: i32, b: i32) -> i32 {
    if a < b { a } else { b }
}

fn dif(a: i32, b: i32) -> i32 {
    if a > b { a - b } else { b - a }
}

fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(7);
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    if down == 1 && prev == 0 {
        host::display::state_set(0, px);
        host::display::state_set(1, py);
        host::display::state_set(2, 1);
    }
    let active: i32 = host::display::state_get(2);
    let ax: i32 = host::display::state_get(0);
    let ay: i32 = host::display::state_get(1);
    if down == 0 && active == 1 {
        host::display::state_set(2, 0);
        host::display::state_set(3, lo2(ax, px));
        host::display::state_set(4, lo2(ay, py));
        host::display::state_set(5, dif(ax, px));
        host::display::state_set(6, dif(ay, py));
    }
    host::display::state_set(7, down);
    host::display::clear(0x101014);
    let cw: i32 = host::display::state_get(5);
    let ch: i32 = host::display::state_get(6);
    if cw > 0 && ch > 0 {
        host::display::fill_rect(host::display::state_get(3), host::display::state_get(4), cw, ch, 0x203a20);
    }
    if active == 1 && down == 1 {
        let x: i32 = lo2(ax, px);
        let y: i32 = lo2(ay, py);
        let bw: i32 = dif(ax, px);
        let bh: i32 = dif(ay, py);
        host::display::fill_rect(x, y, bw, 1, 0x00ff88);
        host::display::fill_rect(x, y + bh, bw, 1, 0x00ff88);
        host::display::fill_rect(x, y, 1, bh, 0x00ff88);
        host::display::fill_rect(x + bw, y, 1, bh, 0x00ff88);
        host::display::draw_number(8, 24, bw, 0xffffff, 1);
        host::display::draw_number(48, 24, bh, 0x808080, 1);
    }
    host::display::draw_string(8, 8, "DRAG TO SELECT A REGION", 0x808080, 1);
    host::display::present();
}
